import os, re
ROOT=os.path.dirname(os.path.abspath(__file__)); SRC=os.path.join(ROOT,"sources"); OUT=os.path.join(ROOT,"skills")
def w(skill,fname,text):
    d=os.path.join(OUT,skill,"references"); os.makedirs(d,exist_ok=True)
    open(os.path.join(d,fname),"w").write(text); print(fname,len(text)); return len(text)
OS=os.path.join(SRC,"opensim-src")
out=["# OpenSim API Catalogue (generated from opensim/opensim source)\n",
"Generated by scanning the C# source of OpenSimulator (BSD). For each file: namespace, public types, and public method signatures. Use it to find where a behaviour lives in the server before reading the source: region modules, ROBUST services, script engines, physics, and the Linden client stack.\n"]
files=[]
for dp,dn,fn in os.walk(OS):
    if any(x in dp for x in ["obj","bin",".git","ThirdParty"]): continue
    for f in fn:
        if f.endswith(".cs"): files.append(os.path.join(dp,f))
files.sort(); nt=0; nm=0
for fp in files:
    rel=os.path.relpath(fp,OS)
    src=open(fp,encoding="utf-8",errors="replace").read()
    ns=re.search(r'^\s*namespace\s+([\w\.]+)', src, re.M)
    types=re.findall(r'^\s*public\s+(?:static\s+|abstract\s+|sealed\s+|partial\s+)*(class|struct|interface|enum)\s+(\w+)', src, re.M)
    if not types: continue
    methods=re.findall(r'^\s*public\s+(?:static\s+|virtual\s+|override\s+|abstract\s+|async\s+|sealed\s+)*([\w<>\[\]\?,\. ]+?)\s+(\w+)\s*\(([^;{}]*)\)\s*(?:\{|;|=>)', src, re.M)
    out.append(f"\n## {rel}\n")
    out.append(f"- Namespace: `{ns.group(1) if ns else '?'}`\n")
    for kind,name in types: out.append(f"- Type: {kind} `{name}`\n"); nt+=1
    for ret,name,args in methods:
        if name in ("get","set"): continue
        out.append(f"  - Method: `{ret.strip()} {name}({' '.join(args.split())[:150]})`\n"); nm+=1
out.insert(2, f"Catalogue covers {len(files)} source files, {nt} public types, {nm} public methods.\n")
print(w("secondlife_opensim_server","opensim-api.md","\n".join(out)))
